css:
/* Кнопка, притягивающаяся к курсору. Цвета берутся из токенов дизайн-системы. */
.magnetic { display: inline-flex; } /* обёртка ровно по размеру кнопки — по ней меряем центр */
.magnetic--block { display: flex; } .magnetic--block .magnetic__btn { width: 100%; } /* кнопка формы на всю ширину */
.magnetic__btn {
  position: relative; isolation: isolate; box-sizing: border-box;
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 48px; padding: 14px 28px; border: 0; border-radius: 999px;
  background: var(--color-primary, #1d4ed8); color: var(--color-on-primary, #ffffff);
  font: inherit; font-weight: 600; line-height: 1.2; text-decoration: none; cursor: pointer;
  transform: translate3d(var(--mx, 0px), var(--my, 0px), 0) scale(var(--ms, 1));
  transition: transform 480ms cubic-bezier(.2, 0, 0, 1); /* мягкий возврат */
}
/* Тень и затемнение — отдельные слои: анимируем только opacity, не box-shadow и не background */
.magnetic__btn::before, .magnetic__btn::after {
  content: ""; position: absolute; inset: 0; z-index: -1; border-radius: inherit;
  opacity: 0; transition: opacity 240ms cubic-bezier(.2, 0, 0, 1); pointer-events: none;
}
.magnetic__btn::before { box-shadow: 0 14px 30px -12px rgba(15, 23, 42, .55); }
/* Светлая кнопка с тёмным текстом: --mag-veil: rgba(255,255,255,.2) */
.magnetic__btn::after { background: var(--mag-veil, rgba(0, 0, 0, .12)); }
.magnetic__label {
  display: inline-block; /* у строчного элемента transform не работает */
  transform: translate3d(calc(var(--mx, 0px) * .5), calc(var(--my, 0px) * .5), 0);
  transition: transform 480ms cubic-bezier(.2, 0, 0, 1);
}
/* Курсор рядом: быстрое слежение, лёгкое увеличение, тень */
.magnetic.is-near .magnetic__btn, .magnetic.is-near .magnetic__label { transition-duration: 240ms; }
.magnetic.is-near .magnetic__btn { --ms: 1.03; }
.magnetic.is-near .magnetic__btn::before, .magnetic.is-near .magnetic__btn::after,
.magnetic__btn:focus-visible::before, .magnetic__btn:focus-visible::after,
.magnetic__btn:active::after { opacity: 1; } /* нажатие видно и без движения: на телефоне и при «уменьшить движение» */
@media (hover: hover) {
  .magnetic__btn:hover::before, .magnetic__btn:hover::after { opacity: 1; }
}
/* Клавиатура не видит притяжения — фокус несёт то же состояние + заметную рамку */
.magnetic__btn:focus-visible { --ms: 1.03; outline: 3px solid var(--color-text, #111827); outline-offset: 4px; }
.magnetic .magnetic__btn:active { --ms: .97; transition-duration: 120ms; }
@media (prefers-reduced-motion: reduce) {
  /* Уровень 2: движение убираем, смену тени и затемнения оставляем короткой (≤ 150ms) */
  .magnetic__btn, .magnetic__label { transform: none !important; transition: none !important; }
  .magnetic__btn::before, .magnetic__btn::after { transition-duration: 150ms; }
}

js:
// Подключать в конце <body> или с defer. Работает только с мышью и без «уменьшить движение».
(() => {
  const mq = matchMedia('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)');
  const items = [...document.querySelectorAll('[data-magnetic]')].slice(0, 3); // не больше трёх
  const PULL = 0.3, MAX = 10, FIELD = 32; // доля пути к курсору, потолок сдвига px, радиус поля px
  let x = -1e4, y = -1e4, raf = 0, on = false; // -1e4 — «курсора нет рядом»
  const put = (el, dx, dy, near) => {
    el.style.setProperty('--mx', dx.toFixed(1) + 'px');
    el.style.setProperty('--my', dy.toFixed(1) + 'px');
    el.classList.toggle('is-near', near);
  };
  const pull = v => Math.max(-MAX, Math.min(MAX, v * PULL));
  const frame = () => {
    raf = 0;
    const rects = items.map(el => el.getBoundingClientRect()); // сначала все замеры, потом записи
    items.forEach((el, i) => {
      const r = rects[i], dx = x - (r.left + r.width / 2), dy = y - (r.top + r.height / 2);
      const near = Math.abs(dx) <= r.width / 2 + FIELD && Math.abs(dy) <= r.height / 2 + FIELD;
      if (near) put(el, pull(dx), pull(dy), true);
      else if (el.classList.contains('is-near')) put(el, 0, 0, false);
    });
  };
  const tick = () => { if (!raf && x > -1e4) raf = requestAnimationFrame(frame); }; // курсор неизвестен — считать нечего
  const move = e => { if (e.pointerType === 'touch') return; x = e.clientX; y = e.clientY; tick(); };
  const reset = () => { cancelAnimationFrame(raf); raf = 0; x = y = -1e4; items.forEach(el => put(el, 0, 0, false)); };
  const out = e => { if (!e.relatedTarget) reset(); }; // курсор ушёл из окна
  const sync = () => {
    const want = mq.matches && items.length > 0;
    if (want === on) return;
    on = want;
    const m = on ? 'addEventListener' : 'removeEventListener';
    document[m]('pointermove', move, { passive: true });
    document[m]('pointerout', out);
    window[m]('scroll', tick, { passive: true }); // прокрутка сдвигает кнопку под неподвижным курсором
    window[m]('blur', reset);
    if (!on) reset();
  };
  mq.addEventListener('change', sync); document.addEventListener('touchstart', () => {}, { passive: true }); // iOS Safari включает :active только при слушателе касаний
  sync();
})();

gsap_alt:
Из npm, без CDN: npm i gsap; import gsap from 'gsap'. Разметку и слои тени оставить; у .magnetic__btn и .magnetic__label убрать из CSS transform и transition (GSAP пишет transform сам, CSS-сглаживание наложилось бы на его твины). quickTo создаётся один раз на свойство, а не новый твин на каждое движение мыши; gsap.matchMedia сам снимает эффект и возвращает кнопки на место при включении «уменьшить движение», mm.revert() — при уходе со страницы.
const mm = gsap.matchMedia();
mm.add('(hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference)', () => {
  const to = (el, prop, duration) => gsap.quickTo(el, prop, { duration, ease: 'power3' });
  const items = gsap.utils.toArray('[data-magnetic]').slice(0, 3).map(wrap => {
    const btn = wrap.querySelector('.magnetic__btn'), label = wrap.querySelector('.magnetic__label');
    return { wrap, btn, near: false, x: to(btn, 'x', 0.48), y: to(btn, 'y', 0.48), lx: to(label, 'x', 0.48), ly: to(label, 'y', 0.48) };
  });
  const clamp = gsap.utils.clamp(-10, 10);
  const set = (it, dx, dy, near) => {
    it.x(dx); it.y(dy); it.lx(dx / 2); it.ly(dy / 2);
    if (near === it.near) return; // масштаб — твином только при смене состояния: quickTo не принимает сокращение scale
    it.near = near; it.wrap.classList.toggle('is-near', near);
    gsap.to(it.btn, { scale: near ? 1.03 : 1, duration: 0.24, ease: 'power3', overwrite: 'auto' });
  };
  const move = e => {
    if (e.pointerType === 'touch') return;
    const rects = items.map(it => it.wrap.getBoundingClientRect());
    items.forEach((it, i) => {
      const r = rects[i], dx = e.clientX - r.left - r.width / 2, dy = e.clientY - r.top - r.height / 2;
      const near = Math.abs(dx) <= r.width / 2 + 32 && Math.abs(dy) <= r.height / 2 + 32;
      set(it, near ? clamp(dx * 0.3) : 0, near ? clamp(dy * 0.3) : 0, near);
    });
  };
  const out = e => { if (!e.relatedTarget) items.forEach(it => set(it, 0, 0, false)); };
  document.addEventListener('pointermove', move, { passive: true });
  document.addEventListener('pointerout', out);
  return () => {
    document.removeEventListener('pointermove', move);
    document.removeEventListener('pointerout', out);
    items.forEach(it => it.wrap.classList.remove('is-near'));
  };
});
